"bea":{perd:[["mrp",{"en":"Forces Bea to spend her lone ammo on porters that do not charge Big Sting, repeatedly interrupting her lane pressure.","fr":"Force Bea à dépenser son unique munition sur des porteurs qui ne chargent pas Big Sting, interrompant sans cesse sa pression de couloir."}],["piper",{"en":"Bursts Bea down at equal range with front-loaded damage before her lone ammo cycles a Supercharged reply.","fr":"Explose Bea à portée égale avec des dégâts immédiats, avant que son unique munition ne lui rende un tir Supercharged."}],["sprout",{"en":"Lobs Seed Bombs over cover and raises hedges against Bea's straight shots, controlling lanes she cannot contest. Also weak to: Thrower Sniper","fr":"Lance des Seed Bombs par-dessus le couvert et dresse des haies face aux tirs droits de Bea, contrôlant des couloirs qu'elle ne peut pas disputer. Faible aussi contre : Thrower Sniper"}]],bat:[["colette",{"en":"Outranges Colette and uses Honeycomb to blunt her percentage-based combo before punishing her with fixed Supercharged burst.","fr":"Porte plus loin que Colette et utilise Honeycomb pour émousser son combo proportionnel avant de la punir d'un burst Supercharged à dégâts fixes."}],["gray",{"en":"Outranges Gray's narrow Finger Pistol, landing wider shots and Supercharged follow-ups to control the long-range exchange.","fr":"Porte plus loin que l'étroit pistolet-doigt de Gray, plaçant des tirs plus larges et des enchaînements Supercharged pour contrôler l'échange à longue portée."}],["jaeyong",{"en":"Outranges Jae-Yong, landing high-damage shots before he closes enough distance for his piercing attacks to connect.","fr":"Porte plus loin que Jae-Yong, plaçant des tirs à gros dégâts avant qu'il ne comble assez de distance pour que ses attaques perforantes touchent."}],["lola",{"en":"Outranges Lola and cycles normal and Supercharged shots to disrupt her firing lane before the Ego establishes crossfire.","fr":"Porte plus loin que Lola et enchaîne tirs normaux et Supercharged pour perturber son couloir de tir avant que l'Ego n'installe un feu croisé."}],["meeple",{"en":"Outranges Meeple and converts opening hits into Supercharged follow-ups before their wall-piercing zone can control cover.","fr":"Porte plus loin que Meeple et transforme ses premières touches en enchaînements Supercharged avant que sa zone perce-murs ne contrôle le couvert."}],["meg",{"en":"Outranges Meg's Mecha and chains Supercharged shots through its high health, breaking the suit before its swing can connect.","fr":"Porte plus loin que le Mecha de Meg et enchaîne les tirs Supercharged à travers sa grande santé, brisant l'armure avant que son coup ne touche."}]]},
"belle":{perd:[["nani",{"en":"Outranges Belle after the orbs converge and threatens a three-projectile burst, forcing her from open sniper lanes.","fr":"Porte plus loin que Belle une fois ses orbes réunies et menace d'un burst à trois projectiles, la chassant des couloirs de tir ouverts."}],["darryl",{"en":"Tanks Belle's poke long enough to roll into point-blank range and overwhelm her with shotgun burst.","fr":"Encaisse le harcèlement de Belle assez longtemps pour rouler jusqu'à bout portant et la submerger d'un burst de fusil."}],["piper",{"en":"Bursts Belle down at equal range with heavier maximum-distance shots before her faster reload can matter.","fr":"Explose Belle à portée égale avec des tirs plus lourds à distance maximale, avant que son rechargement plus rapide ne pèse."}]],bat:[["8bit",{"en":"Stops 8bit from sustaining boosted fire by using Grounded to block his reloads after a mark.","fr":"Empêche 8-Bit d'entretenir son feu amplifié en bloquant ses rechargements avec Grounded après une marque."}],["amber",{"en":"Attacks Amber beyond her reach, then Grounded interrupts the reload cycle she needs for sustained flame pressure.","fr":"Attaque Amber hors de sa portée, puis Grounded coupe le cycle de rechargement dont elle a besoin pour entretenir ses flammes.","es":"Ataca a Amber fuera de su alcance y luego Grounded interrumpe el ciclo de recarga que necesita para mantener la presión de llamas."}],["clancy",{"en":"Pressures Clancy beyond his reach and reloads faster, denying the repeated hits that advance his stages.","fr":"Presse Clancy hors de sa portée et recharge plus vite, lui refusant les touches répétées qui font monter ses paliers."}],["colt",{"en":"Out-trades Colt at maximum range as Positive Feedback absorbs damage from later bullets in each volley.","fr":"Gagne les échanges face à Colt à portée maximale, Positive Feedback absorbant les dégâts des dernières balles de chaque volée."}],["damian",{"en":"Kites Damian beyond punching range, landing Electro-Bolts before he can close the distance.","fr":"Tient Damian à distance hors de portée de ses poings, plaçant ses Electro-Bolts avant qu'il ne comble l'écart."}],["gale",{"en":"Pokes Gale from beyond his snowballs, then marks him to amplify every follow-up hit.","fr":"Harcèle Gale hors de portée de ses boules de neige, puis le marque pour amplifier chaque touche suivante."}],["gene",{"en":"Outranges Gene's full-damage projectile and punishes healing clusters by bouncing Electro-Bolts between nearby allies.","fr":"Porte plus loin que le projectile pleine puissance de Gene et punit les regroupements de soins en faisant rebondir ses Electro-Bolts entre les alliés proches."}],["jacky",{"en":"Slows Jacky's approach with a trap while firing from beyond her short attack radius.","fr":"Ralentit l'approche de Jacky avec un piège tout en tirant hors de son court rayon d'attaque."}],["janet",{"en":"Outranges Janet's fully focused shots and reloads faster, winning repeated lane trades before she retaliates.","fr":"Porte plus loin que les tirs pleinement concentrés de Janet et recharge plus vite, remportant les échanges de couloir répétés avant qu'elle ne riposte."}],["jessie",{"en":"Punishes Jessie for placing Scrappy nearby, chaining Electro-Bolts across both targets from superior range.","fr":"Punit Jessie d'avoir posé Scrappy à côté d'elle, enchaînant ses Electro-Bolts sur les deux cibles depuis une portée supérieure."}],["lily",{"en":"Keeps Lily at range, then uses Grounded to restrict her post-teleport burst by preventing reloads.","fr":"Maintient Lily à distance, puis utilise Grounded pour limiter son burst d'après-téléportation en l'empêchant de recharger."}],["lola",{"en":"Punishes Lola for stacking beside her Ego, chaining Electro-Bolts through both targets from outside her range.","fr":"Punit Lola de se coller à son Ego, enchaînant ses Electro-Bolts à travers les deux cibles hors de sa portée."}],["lou",{"en":"Maintains range against Lou, denying him repeated hits and preventing his freeze buildup.","fr":"Conserve la distance face à Lou, lui refusant les touches répétées et empêchant son gel de s'accumuler."}],["maisie",{"en":"Outranges Maisie and uses Positive Feedback to absorb damage during open-lane trades before Shockwave threatens.","fr":"Porte plus loin que Maisie et utilise Positive Feedback pour absorber les dégâts pendant les échanges en couloir ouvert, avant que Shockwave ne menace."}],["najia",{"en":"Breaks Najia's single-ammo cycle with Grounded , blocking the reload needed for another snake or extended Super.","fr":"Casse le cycle à munition unique de Najia avec Grounded, bloquant le rechargement nécessaire à un nouveau serpent ou à un Super prolongé."}],["stu",{"en":"Pressures Stu beyond his fireworks' reach, forcing risky approaches before he can start chaining dashes.","fr":"Presse Stu hors de portée de ses feux d'artifice, l'obligeant à des approches risquées avant qu'il ne commence à enchaîner ses dashs."}]]},
